// Refresh file metadata and the self-contained local gallery after changing fixtures.
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const assert = require('node:assert/strict');
const root = path.resolve(__dirname, '..');
const manifest = JSON.parse(fs.readFileSync(path.join(__dirname, 'annotations.json'), 'utf8'));
const text = JSON.parse(fs.readFileSync(path.join(__dirname, 'expected-text.json'), 'utf8'));
const escape = value => String(value).replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll('"', '&quot;');

for (const asset of manifest.assets) {
  asset.file = `images/${asset.id}.png`;
  const bytes = fs.readFileSync(path.join(root, asset.file));
  assert.equal(bytes.subarray(0, 8).toString('hex'), '89504e470d0a1a0a');
  asset.width = bytes.readUInt32BE(16);
  asset.height = bytes.readUInt32BE(20);
  asset.bytes = bytes.length;
  asset.sha256 = crypto.createHash('sha256').update(bytes).digest('hex');
}
for (const receipt of Object.values(text.receipts)) {
  assert.equal(receipt.rows.reduce((sum, row) => sum + Math.round(row.amount * 100), 0), Math.round(receipt.subtotal * 100));
  assert.equal(Math.round(receipt.subtotal * 100) + Math.round(receipt.tax * 100), Math.round(receipt.total * 100));
}
assert.deepEqual(text.cropped_capture.visible_ingredient_indices, [0, 1, 2, 3]);
assert.deepEqual(text.cropped_capture.partial_ingredient_indices, [4]);
assert.notEqual(manifest.assets[0].sha256, manifest.assets[1].sha256);
const ids = new Set(manifest.assets.map(a => a.id));
assert.equal(ids.size, manifest.assets.length);
for (const scenario of manifest.scenarios) for (const id of scenario.inputs) assert(ids.has(id), `Unknown fixture: ${id}`);
fs.writeFileSync(path.join(root, 'manifest.json'), JSON.stringify(manifest, null, 2) + '\n');

const order = [...manifest.assets.filter(a => a.category === 'inventory').map(a => a.id), 'receipt-warehouse-clean', 'receipt-warehouse-recapture', 'receipt-mixed-lines', 'recipe-complete', 'recipe-cropped', 'meal-skillet'];
const assets = order.map(id => manifest.assets.find(a => a.id === id));
const cards = assets.map((asset, index) => `<article data-category="${asset.category}"><a class="picture" href="${asset.file}" target="_blank" rel="noopener"><img src="${asset.file}" alt="${escape(asset.title)}"></a><div class="body"><div class="row"><span class="tag">${asset.category}</span><span class="number">${String(index + 1).padStart(2, '0')}</span></div><h2>${escape(asset.title)}</h2><p>${escape(asset.description)}</p><details><summary>Expected behavior</summary><pre>${escape(JSON.stringify(asset.expected, null, 2))}</pre><strong>Should avoid</strong><ul>${asset.must_not.map(t => `<li>${escape(t)}</li>`).join('')}</ul></details><div class="links"><a href="${asset.file}" download>Download PNG ↗</a><span>${asset.width} × ${asset.height}</span></div></div></article>`).join('\n');
const html = `<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kitchen image lab — synthetic fixtures</title><style>
:root { color-scheme:light; --ink:#25362c; --muted:#69746b; --line:#dce1d7; --green:#365c43; } *{box-sizing:border-box} body{margin:0;background:#f6f5ef;color:var(--ink);font:15px/1.5 -apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif} .wrap{max-width:1320px;margin:auto;padding:30px 36px 70px} header{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line);padding-bottom:18px;font-size:12px;letter-spacing:.09em;text-transform:uppercase} header a{color:var(--green);text-transform:none;letter-spacing:0} .hero{padding:40px 0 26px;max-width:800px} .eyebrow{font-size:11px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:var(--green)} h1{font:50px/1.05 Georgia,serif;letter-spacing:-1px;margin:14px 0 16px} .intro{color:var(--muted);font-size:17px;max-width:640px} .stats{display:flex;gap:22px;font-size:12px;color:var(--muted);margin:25px 0}.stats b{color:var(--ink);font-size:17px;margin-right:5px} nav{display:flex;flex-wrap:wrap;gap:8px;margin:0 0 25px} button{font:inherit;font-size:13px;border:1px solid var(--line);background:transparent;color:var(--ink);border-radius:24px;padding:7px 15px;cursor:pointer} button[aria-pressed=true]{background:var(--green);border-color:var(--green);color:#fff}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px} article{background:white;border:1px solid var(--line);border-radius:12px;overflow:hidden;align-self:start} article[hidden]{display:none}.picture{display:block;background:#e7e6df;height:225px;padding:10px;border-bottom:1px solid var(--line)}img{display:block;width:100%;height:100%;object-fit:contain}.body{padding:17px}.row{display:flex;justify-content:space-between;align-items:center}.tag{font-size:10px;letter-spacing:.08em;text-transform:uppercase;background:#edf2e9;color:var(--green);padding:4px 7px;border-radius:4px}.number{color:#97a093;font-size:11px}h2{font:22px/1.2 Georgia,serif;letter-spacing:-.3px;margin:12px 0 9px}p{margin:0 0 14px}.body>p{font-size:13px;color:var(--muted);min-height:58px}details{font-size:12px;margin:16px 0}summary{cursor:pointer;color:var(--green)}pre{font-size:11px;white-space:pre-wrap;overflow-wrap:anywhere;padding:10px;background:#f5f7f2;max-height:260px;overflow:auto}ul{padding-left:16px;color:var(--muted)}li{margin:7px 0}.links{display:flex;justify-content:space-between;gap:6px;border-top:1px solid var(--line);padding-top:12px;align-items:center;font-size:10px;color:var(--muted)}a{color:var(--green)}.links a{font-size:12px;text-decoration:none;font-weight:600}.note{margin-top:30px;padding:20px 0;border-top:1px solid var(--line);color:var(--muted);font-size:12px;max-width:870px}.empty{font-size:13px;color:var(--muted)}@media(max-width:1050px){.grid{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:760px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.wrap{padding:22px}h1{font-size:40px}}@media(max-width:480px){.grid{grid-template-columns:1fr}.picture{height:280px}.stats{gap:12px}header{font-size:10px}.intro{font-size:15px}}
</style><body><div class="wrap"><header><span>Kitchen / Image lab</span><a href="manifest.json">Fixture manifest ↗</a></header><section class="hero"><div class="eyebrow">Development collection · v${manifest.version}</div><h1>Give your agents<br>something to look at.</h1><p class="intro">Receipts, fridge photos, recipes, and cooking moments. Eight synthetic inputs with expected results and explicit uncertainty.</p><div class="stats"><span><b>8</b> images</span><span><b>4</b> workflows</span><span><b>100%</b> synthetic</span></div></section><nav aria-label="Filter fixtures"><button data-filter="all" aria-pressed="true">All images</button><button data-filter="inventory" aria-pressed="false">Inventory</button><button data-filter="receipt" aria-pressed="false">Receipts</button><button data-filter="recipe" aria-pressed="false">Recipes</button><button data-filter="meal" aria-pressed="false">Cooking</button></nav><main class="grid">${cards}</main><p class="note">Photos were created with built-in image generation. Receipt and recipe screenshots were rendered from original HTML so text and arithmetic are reproducible. This is a development set, not a benchmark of real-world performance. Keep annotations and generation prompts separate from the inputs supplied to the agent being evaluated.</p><a href="README.md">Usage notes and scenarios ↗</a></div><script>for(const button of document.querySelectorAll('[data-filter]'))button.addEventListener('click',()=>{for(const b of document.querySelectorAll('[data-filter]'))b.setAttribute('aria-pressed',String(b===button));for(const card of document.querySelectorAll('[data-category]'))card.hidden=button.dataset.filter!=='all'&&card.dataset.category!==button.dataset.filter;});</script></body></html>`;
fs.writeFileSync(path.join(root, 'index.html'), html);
console.log(JSON.stringify({ images: manifest.assets.length, scenarios: manifest.scenarios.length, bytes: manifest.assets.reduce((n,a) => n+a.bytes,0), checks:'PNG signatures/dimensions, receipt arithmetic, crop boundaries, duplicate byte difference, and scenario references passed' }, null, 2));
